#   - CRD configs.kai.scheduler (included in the package as prerequisites/target-facts/default-crds.yaml)
#   - CRD podgroups.scheduling.run.ai (included in the package as prerequisites/target-facts/default-crds.yaml)
#   - CRD queues.scheduling.run.ai (included in the package as prerequisites/target-facts/default-crds.yaml)
#   - CRD schedulingshards.kai.scheduler (included in the package as prerequisites/target-facts/default-crds.yaml)
#   - CRD topologies.kai.scheduler (included in the package as prerequisites/target-facts/default-crds.yaml)
